#include <string>
using namespace std;

// Header file: vehicle.h
#ifndef VEHICLE_H
#define VEHICLE_H

class Vehicle {
protected:
    string brand;
    string model;
    int year;

public:
    Vehicle(string brand, string model, int year) : brand(brand), model(model), year(year) {}

    virtual void displayInfo() const {
        cout << "Brand: " << brand << ", Model: " << model << ", Year: " << year << endl;
    }

    virtual void start() {
        cout << "Vehicle started." << endl;
    }
};

#endif // VEHICLE_H

// Source file: vehicle.cpp
#include "vehicle.h"

// Implementation of virtual functions (if needed)

