#include <iostream>

int main() {
    // Create objects
    Vehicle* vehicle1 = new Car("Toyota", "Camry", 2020);
    Vehicle* vehicle2 = new Bike("Giant", "Bike1000", 2021);

    // Display information
    vehicle1->displayInfo();
    vehicle2->displayInfo();

    // Start vehicles
    vehicle1->start();
    vehicle2->start();

    // Clean up
    delete vehicle1;
    delete vehicle2;

    return 0;
}

