using namespace std;

// Base class: Vehicle
class Vehicle {
protected:
    string brand;
    string model;
    int year;

public:
    Vehicle(string brand, string model, int year) : brand(brand), model(model), year(year) {}

    virtual void displayInfo() {
        cout << "Brand: " << brand << ", Model: " << model << ", Year: " << year << endl;
    }

    virtual void start() {
        cout << "Vehicle started." << endl;
    }
};

// Derived class: Car
class Car : public Vehicle {
public:
    Car(string brand, string model, int year) : Vehicle(brand, model, year) {}

    void start() override {
        cout << "Car started." << endl;
    }
};

// Derived class: Bike
class Bike : public Vehicle {
public:
    Bike(string brand, string model, int year) : Vehicle(brand, model, year) {}

    void start() override {
        cout << "Bike started." << endl;
    }
};

// Main function
int main() {
    // Create objects
    Vehicle* vehicle1 = new Car("Toyota", "Camry", 2020);
    Vehicle* vehicle2 = new Bike("Giant", "Bike1000", 2021);

    // Display information
    vehicle1->displayInfo();
    vehicle2->displayInfo();

    // Start vehicles
    vehicle1->start();
    vehicle2->start();

    // Clean up
    delete vehicle1;
    delete vehicle2;

    return 0;
}

